def count_element_freq(t):
    freq = {}
    for elem in t:
        if isinstance(elem, tuple):
            for sub_elem in elem:
                freq[sub_elem] = freq.get(sub_elem, 0) + 1
        else:
            freq[elem] = freq.get(elem, 0) + 1
    return freq
